import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { decideArgProvenance, isReadOnlyAction, occursAsToken, provLeaves, type ProvActionInfo, type ProvMediatorPin } from './arg-provenance';

// conformance/arg-provenance-vectors.json (generated by scripts/gen-conformance-arg-provenance.mjs from this reference), replayed
// by every native verifier. Every committed expectation is recomputed here, so a reference change that is not regenerated fails.
interface Decision {
  name: string;
  input: { bundle?: unknown; operation: { verb: string; resource: string; params: Record<string, unknown> }; mediators: ProvMediatorPin[]; action?: ProvActionInfo; principal_plan?: boolean; principal_control?: boolean; observed?: never };
  expect: Record<string, unknown>;
}
const doc = JSON.parse(readFileSync(new URL('../conformance/arg-provenance-vectors.json', import.meta.url), 'utf8')) as {
  format: string;
  tokens: { text: string; needle: string; expect: boolean }[];
  leaves: { name: string; value: unknown; expect: string[] | null }[];
  read_only: { name: string; action: ProvActionInfo | null; expect: boolean }[];
  decisions: Decision[];
};

describe('arg-provenance-vectors.json', () => {
  it('format', () => expect(doc.format).toBe('pca-arg-provenance-vectors/1'));
  it.each(doc.tokens)('token $needle in $text', (t) => expect(occursAsToken(t.text, t.needle)).toBe(t.expect));
  it.each(doc.leaves)('leaves $name', (l) => expect(provLeaves(l.value)).toEqual(l.expect));
  it.each(doc.read_only)('read-only $name', (r) => expect(isReadOnlyAction(r.action ?? undefined)).toBe(r.expect));
  it.each(doc.decisions)('decision $name', (c) => {
    const d = decideArgProvenance({
      bundle: c.input.bundle,
      operation: c.input.operation,
      mediators: c.input.mediators,
      ...(c.input.action !== undefined ? { action: c.input.action } : {}),
      principalPlan: c.input.principal_plan === true,
      principalControl: c.input.principal_control === true,
      ...(c.input.observed !== undefined ? { observed: c.input.observed } : {}),
    });
    expect(JSON.parse(JSON.stringify(d))).toEqual(c.expect);
  });
  it('exercises pass, escalate and deny, and every escalate and deny code a native must produce', () => {
    expect(new Set(doc.decisions.map((c) => c.expect.outcome))).toEqual(new Set(['pass', 'escalate', 'deny']));
    const codes = new Set(doc.decisions.map((c) => c.expect.code).filter(Boolean));
    for (const k of ['untrusted_control', 'untrusted_args', 'untrusted_control_and_args', 'malformed_bundle', 'broken_chain', 'bad_signature', 'unbound_action', 'content_mismatch', 'malformed_action', 'malformed_config']) expect(codes.has(k)).toBe(true);
  });
});
